(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-537":{scenario:{company:"Viễn Hà Machinery Works",supervisor:{name:"Hồ Văn Thắng",role:{vi:"Trưởng phòng Kế hoạch Sản xuất",en:"Production Planning Manager"}},ref_code:"MPS-W46",title:{vi:"Đúng điểm thắt. Đúng nhu cầu ròng. Đúng cam kết.",en:"Right bottleneck. Right net demand. Right promise."},brief:{vi:"Bạn chốt kế hoạch sản xuất tuần 46, hồ sơ MPS-W46. Sản phẩm SP-7720 có nhu cầu gộp 4860 cái; tồn kho khả dụng 1240; nhận theo kế hoạch 600; tồn kho an toàn 450; bội số lô 120 cái mỗi pallet. Bản nháp chọn điểm thắt cổ chai theo tổng giờ tải và đặt lệnh 3120 cái. Dùng terminal để chẩn đoán, sửa trạm thắt cổ chai và số lượng lệnh sản xuất, rồi lập báo cáo có căn cứ.",en:"You are closing the week 46 production plan, file MPS-W46. Product SP-7720 has gross demand of 4860 units; available stock 1240; scheduled receipts 600; safety stock 450; lot multiple 120 units per pallet. The draft picks the bottleneck by total load hours and releases an order of 3120 units. Use the terminal to diagnose, correct the bottleneck work center and the order quantity, then write an evidence-based report."},reference_title:{vi:"Bảng cân đối tải - năng lực & dữ liệu MRP đã duyệt · MPS-W46",en:"Approved load-capacity balance & MRP data · MPS-W46"},fields:[{id:"BOTTLENECK",label:{vi:"Trạm thắt cổ chai tuần 46",en:"Week 46 bottleneck work center"},initial:"WC-ASSY",expected:"WC-CNC",choices:["WC-ASSY","WC-CNC","WC-PRESS"],reference:"Bảng cân đối tải - năng lực tuần 46",hint:{vi:"Điểm thắt cổ chai là trạm có tỷ lệ tải trên năng lực cao nhất, không phải trạm nhiều giờ tải nhất.",en:"The bottleneck is the work center with the highest load-to-capacity ratio, not the most load hours."}},{id:"PLAN_QTY",label:{vi:"Số lượng lệnh sản xuất SP-7720",en:"SP-7720 production order quantity"},initial:"3120",expected:"3480",reference:"Bản ghi MRP SP-7720",ref_value:{vi:"Nhu cầu gộp 4860; tồn khả dụng 1240; nhận theo kế hoạch 600; tồn an toàn 450; bội số 120",en:"Gross demand 4860; available 1240; scheduled receipts 600; safety stock 450; multiple 120"},hint:{vi:"Nhu cầu ròng phải bù lại tồn kho an toàn trước khi làm tròn lên theo bội số lô.",en:"Net demand must restore safety stock before rounding up to the lot multiple."}}],sop32:{vi:"Nhu cầu ròng = nhu cầu gộp - tồn kho khả dụng - nhận theo kế hoạch + tồn kho an toàn; số lượng lệnh = nhu cầu ròng làm tròn lên bội số lô 120.",en:"Net requirement = gross demand - available stock - scheduled receipts + safety stock; order quantity = net requirement rounded up to the lot multiple of 120."},context:{label:"APS / MPS-W46",metrics:[{label:{vi:"Nhu cầu gộp SP-7720",en:"SP-7720 gross demand"},value:"4860"},{label:{vi:"Tồn khả dụng + nhận KH",en:"Available + receipts"},value:"1240 + 600"},{label:{vi:"Tồn kho an toàn",en:"Safety stock"},value:"450"},{label:{vi:"Bội số lô",en:"Lot multiple"},value:"120"}]},crisis:{vi:"Giám đốc Kinh doanh yêu cầu: “Xếp cho tổ CNC tăng ca 4 giờ mỗi ngày suốt tháng và hoãn bảo trì định kỳ máy CNC. Cứ báo khách là đơn hàng đang chạy rồi, chuyện sau tính sau.”",en:"The Sales Director demands: “Schedule the CNC team for 4 hours of overtime every day all month and postpone CNC preventive maintenance. Tell the customer the order is already running, we'll deal with it later.”"},options:{safe:{vi:"Từ chối lịch vượt giới hạn làm thêm giờ và bỏ bảo trì, báo Giám đốc Nhà máy, đề xuất phương án hợp lệ: gia công ngoài, giao từng phần, tăng ca trong giới hạn luật và thông báo khách ngày giao thực tế.",en:"Refuse a schedule that breaks overtime limits and skips maintenance, inform the Plant Manager and propose valid options: subcontracting, partial delivery, overtime within legal limits and an honest delivery date."},shortcut:{vi:"Xếp tăng ca 4 giờ mỗi ngày, hoãn bảo trì và báo khách đơn đang chạy.",en:"Schedule 4 hours of daily overtime, postpone maintenance and tell the customer the order is running."},wait:{vi:"Không xếp lịch, chờ kinh doanh và sản xuất tự thống nhất.",en:"Do not schedule anything and wait for Sales and Production to agree."}},questions:{vi:["Vì sao WC-CNC mới là điểm thắt cổ chai dù WC-ASSY có nhiều giờ tải hơn? Số liệu tải, năng lực nào chứng minh?","Trình bày cách tính nhu cầu ròng, số lượng lệnh và cách bạn cam kết ngày giao trung thực khi năng lực không đủ."],en:["Why is WC-CNC the bottleneck although WC-ASSY carries more load hours? Which load and capacity figures prove it?","Explain how you computed net requirement and order quantity, and how you give an honest delivery promise when capacity is short."]},hints:{vi:["Chạy load --week 46 và tính tỷ lệ tải trên năng lực cho từng trạm.","Dùng inv sp-7720 và cat demand.txt, làm đủ các bước gộp ra ròng rồi làm tròn theo SOP mục 3.2.","Đọc lại SOP mục 4.2: kế hoạch không được vượt giới hạn làm thêm giờ hay bỏ bảo trì; mọi áp lực phải được báo cáo."],en:["Run load --week 46 and compute the load-to-capacity ratio of each work center.","Use inv sp-7720 and cat demand.txt, go through gross-to-net, then round up as SOP 3.2 requires.","Re-read SOP 4.2: plans must not break overtime limits or skip maintenance; any pressure must be escalated."]},terminal:{system:"aps-ctl",settable:["BOTTLENECK","PLAN_QTY"],commands:[{cmd:"status",out:{vi:"MPS-W46 nháp: 3 trạm công việc, 1 cảnh báo quá tải chưa xử lý; lệnh SP-7720 chờ phê duyệt",en:"MPS-W46 draft: 3 work centers, 1 unresolved overload alert; SP-7720 order awaiting approval"}},{cmd:"load --week 46",out:{vi:"WC-ASSY tải 420 h / năng lực 480 h; WC-CNC tải 310 h / năng lực 264 h; WC-PRESS tải 198 h / năng lực 240 h",en:"WC-ASSY load 420 h / capacity 480 h; WC-CNC load 310 h / capacity 264 h; WC-PRESS load 198 h / capacity 240 h"}},{cmd:"cat calendar.txt",out:{vi:"WC-CNC: 2 máy x 6 ngày x 2 ca x 11 h hiệu dụng = 264 h; đã trừ 1 lượt bảo trì định kỳ",en:"WC-CNC: 2 machines x 6 days x 2 shifts x 11 effective h = 264 h; one preventive maintenance slot deducted"}},{cmd:"inv sp-7720",out:{vi:"Tồn kho khả dụng 1240; nhận theo kế hoạch tuần 46: 600; tồn kho an toàn 450",en:"Available stock 1240; scheduled receipts week 46: 600; safety stock 450"}},{cmd:"cat demand.txt",out:{vi:"SP-7720 tuần 46: nhu cầu gộp 4860 (đơn hàng 4260 + dự báo 600); bội số lô 120 cái mỗi pallet",en:"SP-7720 week 46: gross demand 4860 (orders 4260 + forecast 600); lot multiple 120 units per pallet"}}]}},learning:{summary:{vi:"Kỹ sư Hoạch định & Điều độ Sản xuất biến nhu cầu bán hàng thành kế hoạch sản xuất khả thi: lập kế hoạch tổng thể, MPS, MRP, cân đối tải - năng lực, điều độ lệnh theo ngày, ca và theo dõi tiến độ để giao hàng đúng hẹn với tồn kho, chi phí hợp lý. Nghề đòi hỏi tư duy hệ thống, tính toán chính xác, hiểu ràng buộc nhà máy và dám nói thật về năng lực.",en:"A Production Planning & Control engineer turns sales demand into a feasible production plan: aggregate planning, MPS, MRP, load-capacity balancing, daily and shift scheduling and progress tracking to deliver on time with sensible inventory and cost. The role requires systems thinking, accurate calculations, understanding of plant constraints and the courage to be honest about capacity."},responsibilities:{vi:["Lập kế hoạch sản xuất tổng thể và lịch sản xuất chính (MPS) từ dự báo, đơn hàng.","Chạy MRP: tính nhu cầu ròng, lệnh sản xuất, lệnh mua theo thời gian chờ và bội số lô.","Cân đối tải - năng lực, xác định điểm thắt cổ chai và đề xuất phương án tăng năng lực.","Điều độ lệnh theo ca, theo dõi tiến độ, xử lý thay đổi đơn hàng và sự cố.","Phối hợp kinh doanh, mua hàng, kho, bảo trì, chất lượng để cam kết ngày giao khả thi."],en:["Build the aggregate plan and master production schedule (MPS) from forecasts and orders.","Run MRP: compute net requirements and production and purchase orders with lead times and lot multiples.","Balance load and capacity, identify bottlenecks and propose capacity options.","Schedule orders by shift, track progress and handle order changes and disruptions.","Coordinate sales, purchasing, warehouse, maintenance and quality to commit feasible dates."]},competencies:[{name:{vi:"Logic MRP",en:"MRP logic"},desc:{vi:"Tính đúng từ nhu cầu gộp ra nhu cầu ròng, bù tồn an toàn, dịch thời gian chờ và làm tròn lô.",en:"Go correctly from gross to net, restore safety stock, offset lead times and round lots."}},{name:{vi:"Hoạch định năng lực",en:"Capacity planning"},desc:{vi:"Tính năng lực hiệu dụng, tỷ lệ tải và phát hiện điểm thắt cổ chai thật sự.",en:"Compute effective capacity and load ratios and find the true bottleneck."}},{name:{vi:"Điều độ & ưu tiên",en:"Scheduling & prioritization"},desc:{vi:"Áp dụng quy tắc ưu tiên, giảm thời gian chuyển đổi và giữ nhịp cho trạm thắt cổ chai.",en:"Apply priority rules, cut changeover time and keep the bottleneck running."}},{name:{vi:"Phân tích dữ liệu",en:"Data analysis"},desc:{vi:"Dùng ERP, APS và bảng tính để mô phỏng kịch bản và đo độ chính xác kế hoạch.",en:"Use ERP, APS and spreadsheets to simulate scenarios and measure plan accuracy."}},{name:{vi:"Cam kết trung thực",en:"Honest commitment"},desc:{vi:"Không hứa ngày giao vượt năng lực thật, không đánh đổi an toàn và luật lao động lấy tiến độ.",en:"Never promise dates beyond real capacity or trade safety and labor law for speed."}}],knowledge:{vi:["Khung hoạch định sản xuất: S&OP, kế hoạch tổng thể, MPS, MRP, CRP theo bộ kiến thức CPIM.","Logic MRP: nhu cầu gộp, tồn khả dụng, nhận theo kế hoạch, tồn an toàn, thời gian chờ, quy tắc lô (L4L, FOQ, bội số, EOQ).","Lý thuyết ràng buộc (TOC) và phương pháp Drum - Buffer - Rope.","Quy tắc điều độ: FIFO, SPT, EDD và biểu đồ Gantt.","Bộ luật Lao động 2019, Điều 107 về giới hạn làm thêm giờ: không quá 40 giờ/tháng và 200 giờ/năm, trừ trường hợp luật cho phép 300 giờ."],en:["Production planning framework: S&OP, aggregate plan, MPS, MRP and CRP per the CPIM body of knowledge.","MRP logic: gross demand, available stock, scheduled receipts, safety stock, lead time and lot rules (L4L, FOQ, multiples, EOQ).","Theory of Constraints (TOC) and the Drum - Buffer - Rope method.","Scheduling rules: FIFO, SPT, EDD and Gantt charts.","Labor Code 2019, Article 107 on overtime limits: no more than 40 hours per month and 200 hours per year, or 300 where the law allows."]},tools:["Hệ thống ERP (phân hệ MRP)","Phần mềm APS điều độ","Bảng tính kế hoạch (Excel)","Bảng Gantt & bảng điều độ trực quan","Hệ thống MES theo dõi tiến độ"],kpis:{vi:["Tỷ lệ giao hàng đúng hẹn, đủ số lượng (OTIF).","Mức độ tuân thủ kế hoạch sản xuất tuần.","Số vòng quay tồn kho thành phẩm và bán thành phẩm.","Hiệu suất sử dụng trạm thắt cổ chai."],en:["On-time in-full (OTIF) delivery rate.","Weekly schedule adherence.","Finished goods and WIP inventory turns.","Bottleneck utilization."]},day:[{time:"07:30",vi:"Kiểm tra sản lượng ca đêm trên MES, cập nhật lệnh bị trễ.",en:"Check night-shift output in MES and update late orders."},{time:"09:00",vi:"Chạy MRP, rà thông điệp đề xuất lệnh mới, dời hoặc hủy lệnh.",en:"Run MRP and review messages to release, reschedule or cancel orders."},{time:"11:00",vi:"Cân đối tải - năng lực tuần tới, xác định trạm thắt cổ chai.",en:"Balance next week's load and capacity and identify the bottleneck."},{time:"14:00",vi:"Họp S&OP với kinh doanh, mua hàng, bảo trì về đơn gấp và lịch bảo trì.",en:"Join the S&OP meeting with sales, purchasing and maintenance on rush orders and maintenance slots."},{time:"16:30",vi:"Phát hành lịch điều độ ngày mai và thông báo ngày giao cam kết.",en:"Release tomorrow's dispatch list and confirm committed delivery dates."}],mistakes:{vi:["Xác định điểm thắt cổ chai theo tổng giờ tải thay vì tỷ lệ tải trên năng lực.","Quên bù tồn kho an toàn hoặc bỏ sót lượng nhận theo kế hoạch khi tính nhu cầu ròng.","Hứa ngày giao bằng cách tăng ca vượt giới hạn luật và cắt bảo trì định kỳ."],en:["Picking the bottleneck by total load hours instead of load-to-capacity ratio.","Forgetting to restore safety stock or missing scheduled receipts in net requirements.","Promising dates through illegal overtime and skipped preventive maintenance."]},career:[{vi:"Nhân viên điều độ sản xuất",en:"Production scheduler"},{vi:"Kỹ sư hoạch định sản xuất (PPC)",en:"Production planning engineer (PPC)"},{vi:"Trưởng nhóm kế hoạch, S&OP",en:"Planning & S&OP lead"},{vi:"Trưởng phòng Kế hoạch & Chuỗi cung ứng nhà máy",en:"Plant planning & supply chain manager"}],glossary:[{term:"MPS",vi:"Lịch sản xuất chính: sản phẩm gì, bao nhiêu, khi nào, làm đầu vào cho MRP.",en:"Master production schedule: what, how many and when to build, feeding MRP."},{term:"MRP",vi:"Hoạch định nhu cầu vật tư: tính nhu cầu ròng và thời điểm phát lệnh sản xuất, mua hàng.",en:"Material requirements planning: computing net needs and when to release production and purchase orders."},{term:"Điểm thắt cổ chai",vi:"Tài nguyên có năng lực nhỏ hơn hoặc sát nhu cầu nhất, quyết định sản lượng toàn hệ thống.",en:"Bottleneck: the resource with capacity below or closest to demand, setting total system output."},{term:"Tồn kho an toàn",vi:"Lượng tồn dự phòng để hấp thụ biến động nhu cầu và thời gian chờ.",en:"Safety stock: buffer inventory that absorbs demand and lead-time variability."},{term:"OTIF",vi:"Tỷ lệ đơn hàng giao đúng hẹn và đủ số lượng theo cam kết.",en:"On-time in-full: share of orders delivered on the promised date and in full quantity."}],quiz:[{q:{vi:"Nhu cầu gộp 1000, tồn khả dụng 300, nhận theo kế hoạch 200, tồn an toàn 100, bội số lô 250. Số lượng lệnh sản xuất là bao nhiêu?",en:"Gross demand 1000, available 300, scheduled receipts 200, safety stock 100, lot multiple 250. What is the order quantity?"},options:{vi:["500 cái","600 cái","750 cái","1000 cái"],en:["500 units","600 units","750 units","1000 units"]},answer:2,explain:{vi:"Nhu cầu ròng = 1000 - 300 - 200 + 100 = 600, làm tròn lên bội số 250 được 750.",en:"Net = 1000 - 300 - 200 + 100 = 600, rounded up to a multiple of 250 gives 750."}},{q:{vi:"Cách xác định điểm thắt cổ chai đúng nhất là gì?",en:"What is the right way to identify the bottleneck?"},options:{vi:["Trạm có tỷ lệ tải trên năng lực cao nhất","Trạm có nhiều giờ tải nhất","Trạm có nhiều công nhân nhất","Trạm có máy đắt tiền nhất"],en:["The station with the highest load-to-capacity ratio","The station with the most load hours","The station with the most workers","The station with the most expensive machine"]},answer:0,explain:{vi:"Điểm thắt cổ chai là nơi nhu cầu vượt hoặc sát năng lực nhất, đo bằng tỷ lệ tải trên năng lực.",en:"The bottleneck is where demand exceeds or nearly equals capacity, measured by load-to-capacity ratio."}},{q:{vi:"Kinh doanh yêu cầu tăng ca vượt giới hạn và hoãn bảo trì để kịp đơn. Bạn làm gì?",en:"Sales asks for overtime beyond limits and postponed maintenance to meet an order. What do you do?"},options:{vi:["Làm theo vì khách hàng quan trọng","Tăng ca nhưng không ghi vào bảng chấm công","Hoãn bảo trì, giữ tăng ca trong giới hạn","Từ chối, báo Giám đốc Nhà máy và đề xuất phương án hợp lệ"],en:["Comply since the customer matters","Add overtime but keep it off the timesheet","Postpone maintenance but keep overtime legal","Refuse, inform the Plant Manager and propose valid options"]},answer:3,explain:{vi:"Vượt giới hạn làm thêm giờ và bỏ bảo trì vi phạm luật, tăng rủi ro tai nạn và hỏng máy.",en:"Exceeding overtime limits and skipping maintenance break the law and raise accident and breakdown risks."}},{q:{vi:"Theo Bộ luật Lao động 2019, số giờ làm thêm tối đa trong một tháng là bao nhiêu?",en:"Under the Labor Code 2019, what is the maximum overtime in one month?"},options:{vi:["30 giờ","40 giờ","60 giờ","80 giờ"],en:["30 hours","40 hours","60 hours","80 hours"]},answer:1,explain:{vi:"Điều 107 quy định không quá 40 giờ trong 01 tháng và không quá 50% số giờ làm việc bình thường trong 01 ngày.",en:"Article 107 caps overtime at 40 hours per month and 50% of normal daily hours."}}],tools_en:["ERP system (MRP module)","APS scheduling software","Planning spreadsheets (Excel)","Gantt charts & visual scheduling boards","MES for production progress tracking"]}}})})(window.KKR);
